import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun mod(a: Long, m: Long): Long {
    if (m == 0L) return 0L
    var r = a % m
    if (r < 0) r += m
    return r
}

fun multiplyMatrices(A: Array<LongArray>, B: Array<LongArray>, m: Long): Array<LongArray> {
    val n = A.size
    val k = B.size
    val p = B[0].size
    val C = Array(n) { LongArray(p) }
    for (i in 0 until n) {
        for (l in 0 until k) {
            val aVal = A[i][l]
            if (aVal == 0L) continue
            for (j in 0 until p) {
                C[i][j] = (C[i][j] + aVal * B[l][j]) % m
            }
        }
    }
    return C
}

fun identityMatrix(size: Int, m: Long): Array<LongArray> {
    return Array(size) { i -> LongArray(size) { j -> if (i == j) (1L % m) else 0L } }
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val line = br.readLine()
    val st = StringTokenizer(line)
    val n = st.nextToken().toLong()
    val sx = st.nextToken().toLong()
    val sy = st.nextToken().toLong()
    val dx = st.nextToken().toLong()
    val dy = st.nextToken().toLong()
    val t = st.nextToken().toLong()

    val modN = n

    val X0 = mod(sx - 1, modN)
    val Y0 = mod(sy - 1, modN)
    val dx0 = mod(dx, modN)
    val dy0 = mod(dy, modN)
    val i0 = 0L
    val constVal = 1L % modN

    val vec = arrayOf(
        longArrayOf(X0),
        longArrayOf(Y0),
        longArrayOf(dx0),
        longArrayOf(dy0),
        longArrayOf(i0),
        longArrayOf(constVal)
    )

    // Transition matrix M (6x6)
    val M = arrayOf(
        longArrayOf(2, 1, 1, 0, 1, 2),
        longArrayOf(1, 2, 0, 1, 1, 2),
        longArrayOf(1, 1, 1, 0, 1, 2),
        longArrayOf(1, 1, 0, 1, 1, 2),
        longArrayOf(0, 0, 0, 0, 1, 1),
        longArrayOf(0, 0, 0, 0, 0, 1)
    )

    for (i in M.indices) {
        for (j in M[i].indices) {
            M[i][j] = mod(M[i][j], modN)
        }
    }

    var result = identityMatrix(6, modN)
    var base = M
    var p = t
    while (p > 0) {
        if (p and 1L == 1L) {
            result = multiplyMatrices(result, base, modN)
        }
        base = multiplyMatrices(base, base, modN)
        p = p shr 1
    }

    val finalVec = multiplyMatrices(result, vec, modN)

    val X = finalVec[0][0]
    val Y = finalVec[1][0]

    println("${X + 1} ${Y + 1}")
}
